// Independent physical350 Jacobi replay over QQ[z0,...,z7], through degree5.
// Quadratic physical coefficient pairs are generated by the reviewer's x5
// exponent engine.  Graded convolution omits only terms of degree>5.
#include <flint/fmpq_mpoly.h>
#include <array>
#include <vector>
#include <string>
#include <fstream>
#include <iostream>
#include <cassert>
using namespace std;
fmpq_mpoly_ctx_t ctx;
struct Poly{fmpq_mpoly_t p;Poly(){fmpq_mpoly_init(p,ctx);}Poly(const Poly&x):Poly(){fmpq_mpoly_set(p,x.p,ctx);}Poly(Poly&&x):Poly(){fmpq_mpoly_swap(p,x.p,ctx);}Poly&operator=(Poly x){fmpq_mpoly_swap(p,x.p,ctx);return *this;}~Poly(){fmpq_mpoly_clear(p,ctx);}};
void readpoly(istream&in,Poly&p){int n;in>>n;fmpq_t q;fmpq_init(q);for(int i=0;i<n;i++){string c;ulong ex[8];in>>c;for(int j=0;j<8;j++)in>>ex[j];assert(!fmpq_set_str(q,c.c_str(),10));fmpq_canonicalise(q);fmpq_mpoly_push_term_fmpq_ui(p.p,q,ex,ctx);}fmpq_mpoly_sort_terms(p.p,ctx);fmpq_mpoly_combine_like_terms(p.p,ctx);fmpq_clear(q);}
int main(int argc,char**argv){assert(argc==2);fmpq_mpoly_ctx_init(ctx,8,ORD_DEGLEX);{
ifstream in(argv[1]);vector<vector<Poly>>raw(6,vector<Poly>(150)),expected(6,vector<Poly>(350));
for(auto&grade:raw)for(auto&p:grade)readpoly(in,p);
vector<vector<array<int,3>>>jacobi(350);for(auto&row:jacobi){int n;in>>n;for(int j=0;j<n;j++){array<int,3>term;in>>term[0]>>term[1]>>term[2];row.push_back(term);}}
vector<vector<pair<int,int>>>divergence(25);for(auto&row:divergence){int n;in>>n;for(int j=0;j<n;j++){int i,c;in>>i>>c;row.push_back({i,c});}}
for(auto&grade:expected)for(auto&p:grade)readpoly(in,p);assert(in.good()||in.eof());
Poly product,sum,tmp,scaled;long checked=0;
for(int degree=0;degree<=5;degree++){
 vector<Poly>cache(150*151/2);vector<char>made(cache.size(),0);
 auto pairindex=[](int a,int b){if(a>b)swap(a,b);return b*(b+1)/2+a;};
 for(int row=0;row<350;row++){
  fmpq_mpoly_zero(sum.p,ctx);
  for(auto term:jacobi[row]){int a=term[0],b=term[1],co=term[2],id=pairindex(a,b);
   if(!made[id]){made[id]=1;for(int k=0;k<=degree;k++){if(fmpq_mpoly_is_zero(raw[k][a].p,ctx)||fmpq_mpoly_is_zero(raw[degree-k][b].p,ctx))continue;fmpq_mpoly_mul(tmp.p,raw[k][a].p,raw[degree-k][b].p,ctx);fmpq_mpoly_add(cache[id].p,cache[id].p,tmp.p,ctx);}}
   fmpq_mpoly_scalar_mul_si(scaled.p,cache[id].p,co,ctx);fmpq_mpoly_add(sum.p,sum.p,scaled.p,ctx);
  }
  if(!fmpq_mpoly_equal(sum.p,expected[degree][row].p,ctx)){cerr<<"MISMATCH degree "<<degree<<" physicalrow "<<row<<'\n';return 3;}checked++;
 }
 for(int row=0;row<25;row++){fmpq_mpoly_zero(sum.p,ctx);for(auto term:divergence[row]){fmpq_mpoly_scalar_mul_si(scaled.p,raw[degree][term.first].p,term.second,ctx);fmpq_mpoly_add(sum.p,sum.p,scaled.p,ctx);}assert(fmpq_mpoly_is_zero(sum.p,ctx));}
 cout<<"ALL350_PHYSICAL_QQ_DEGREE_"<<degree<<"_PASS\n";
}
assert(checked==2100);cout<<"ALL25_DIVERGENCE_ALL6GRADES_PASS\n";
}fmpq_mpoly_ctx_clear(ctx);flint_cleanup();}
